<?php
namespace App\Http\Controllers; use App\Models\LaptopDetail; use Illuminate\Http\Request; class LaptopController extends Controller {public function index(){return view('laptops.index',['laptops'=>LaptopDetail::latest()->paginate(20)]);} public function store(Request $r){LaptopDetail::create($r->validate(['model'=>'required|string|max:255','brand'=>'nullable|string|max:100','processor'=>'nullable|string|max:100','ram'=>'nullable|string|max:100','storage'=>'nullable|string|max:100','display_size'=>'nullable|string|max:50','display_status'=>'nullable|string|max:50','screen_condition'=>'nullable|string|max:50','battery_condition'=>'nullable|string|max:50','remarks'=>'nullable|string','quantity'=>'required|integer|min:1','buying_price'=>'required|numeric|min:0','selling_price'=>'required|numeric|min:0']));return back()->with('success','Laptop details save ho gayi.');}}
